  "inlineSchema": "// === Conexión y generador ===\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\n// === Roles: añadimos CHOFER y EMPRESA ===\n// OCP: ampliamos el enum sin romper flujos existentes.\nenum Rol {\n  ADMIN\n  MECANICO\n  ASISTENTE\n  CHOFER\n  EMPRESA\n}\n\n// === Usuarios ===\nmodel Usuario {\n  id             Int      @id @default(autoincrement())\n  nombreCompleto String\n  correo         String   @unique\n  hashClave      String\n  rol            Rol      @default(ASISTENTE)\n  creadoEn       DateTime @default(now())\n  actualizadoEn  DateTime @updatedAt\n\n  // Si pertenece a una empresa\n  empresaId Int?\n  empresa   Empresa? @relation(fields: [empresaId], references: [id])\n\n  // Relaciones\n  vehiculosCreados    Vehiculo[]     @relation(\"VehiculosCreados\")\n  vehiculosComoChofer Vehiculo[]     @relation(\"ChoferVehiculo\")\n  notificaciones      Notificacion[]\n}\n\nmodel Empresa {\n  id          Int        @id @default(autoincrement())\n  razonSocial String\n  ruc         String     @unique\n  creadoEn    DateTime   @default(now())\n  usuarios    Usuario[]\n  vehiculos   Vehiculo[]\n}\n\n// === Vehículos con datos para reglas de notificación ===\nmodel Vehiculo {\n  id     Int     @id @default(autoincrement())\n  placa  String  @unique\n  marca  String\n  modelo String\n  anio   Int\n  color  String\n  vin    String?\n\n  // Auditoría de creación\n  creadoPorId Int\n  creadoPor   Usuario @relation(\"VehiculosCreados\", fields: [creadoPorId], references: [id])\n\n  // Pertenencia (opcional)\n  empresaId Int?\n  empresa   Empresa? @relation(fields: [empresaId], references: [id])\n\n  // Chofer principal (para notificar)\n  choferId Int?\n  chofer   Usuario? @relation(\"ChoferVehiculo\", fields: [choferId], references: [id])\n\n  // --- Datos operativos para CU-03 ---\n  kms                       Int       @default(0) // odómetro actual\n  proximoMantenimientoKm    Int? // umbral por km\n  proximoMantenimientoFecha DateTime? // umbral por fecha\n\n  creadoEn      DateTime @default(now())\n  actualizadoEn DateTime @updatedAt\n\n  // Llantas asociadas (para vencimientos)\n  llantas      Llanta[]\n  Notificacion Notificacion[]\n\n  @@index([choferId])\n  @@index([empresaId])\n}\n\nmodel Llanta {\n  id               Int       @id @default(autoincrement())\n  vehiculoId       Int\n  vehiculo         Vehiculo  @relation(fields: [vehiculoId], references: [id])\n  posicion         String? // ej. \"DI-IZQ\", \"TR-DR\"\n  fechaInstalacion DateTime?\n  fechaVencimiento DateTime // usado por la regla de vencimiento\n  vidaUtilKm       Int? // si luego deseas calcular por km\n\n  creadoEn DateTime @default(now())\n\n  @@index([vehiculoId])\n  @@index([fechaVencimiento])\n}\n\n// === Notificaciones In-App (historial y estado) ===\nmodel Notificacion {\n  id        Int     @id @default(autoincrement())\n  usuarioId Int\n  usuario   Usuario @relation(fields: [usuarioId], references: [id])\n\n  vehiculoId Int?\n  vehiculo   Vehiculo? @relation(fields: [vehiculoId], references: [id])\n\n  tipo        TipoNotificacion\n  mensaje     String\n  prioridad   PrioridadNotificacion @default(MEDIA)\n  estado      EstadoNotificacion    @default(PENDIENTE)\n  fechaLimite DateTime?\n  creadoEn    DateTime              @default(now())\n\n  @@index([usuarioId, estado])\n  @@index([vehiculoId])\n}\n\nenum TipoNotificacion {\n  MANTENIMIENTO_KM\n  MANTENIMIENTO_FECHA\n  VENCIMIENTO_LLANTA\n}\n\nenum PrioridadNotificacion {\n  BAJA\n  MEDIA\n  ALTA\n}\n\nenum EstadoNotificacion {\n  PENDIENTE\n  LEIDA\n}\n",
